const app=getApps().length?getApp():initializeApp(firebaseConfig),auth=getAuth(app),db=getFirestore(app),ADMIN_EMAIL='gogogen98@gmail.com';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],won=v=>Number(v||0).toLocaleString('ko-KR')+'원';
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const categoryNames={record:'다이어리·노트',deco:'스티커·마테',custom:'주문제작',write:'펜·필기',hobby:'취미·DIY',pouch:'파우치·소품',gift:'랜덤박스'};
