function toast(message){const el=$('#admin-toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2400)}
function dateValue(value){if(!value)return '';return typeof value.toDate==='function'?value.toDate().toISOString():value}
function displayDate(value,withTime=false){const raw=dateValue(value);if(!raw)return '-';return new Date(raw).toLocaleString('ko-KR',withTime?{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}:{year:'numeric',month:'2-digit',day:'2-digit'})}
function rows(snapshot){return snapshot.docs.map(row=>({id:row.id,...row.data()}))}

function showGate(kind='login'){
 let gate=$('#admin-auth-gate');
 if(!gate){document.body.insertAdjacentHTML('beforeend',`<section class="admin-auth-gate" id="admin-auth-gate"><div><img src="assets/moodnote-logo-v4.png" alt="moodnote"/><small>SELLER CENTER</small><h1>운영자 로그인</h1><p id="admin-gate-message"></p><button class="primary" id="admin-login">Google 계정으로 로그인</button><a href="index.html">쇼핑몰로 돌아가기</a></div></section>`);gate=$('#admin-auth-gate');$('#admin-login').addEventListener('click',async()=>{try{if(auth.currentUser)await signOut(auth);const provider=new GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});await signInWithPopup(auth,provider)}catch(error){if(!['auth/popup-closed-by-user','auth/cancelled-popup-request'].includes(error.code))toast('로그인에 실패했습니다. 다시 시도해주세요.')}})}
 gate.hidden=false;document.documentElement.classList.add('admin-locked');$('#admin-gate-message').textContent=kind==='denied'?'이 계정에는 판매자센터 권한이 없습니다. 무드노트 운영자 계정으로 다시 로그인해주세요.':'판매자 계정으로 로그인하면 실시간 주문과 상품을 관리할 수 있습니다.';$('#admin-login').textContent=kind==='denied'?'다른 Google 계정으로 로그인':'Google 계정으로 로그인';
}
function unlock(){const gate=$('#admin-auth-gate');if(gate)gate.hidden=true;document.documentElement.classList.remove('admin-locked')}
function listen(){adminUI.listen();subscriptions.forEach(stop=>stop());subscriptions=[];const watch=(name,callback)=>subscriptions.push(onSnapshot(collection(db,name),snap=>callback(rows(snap)),error=>{console.error(name,error);toast(`${name} 데이터를 불러오지 못했습니다.`)}));
 watch('products',data=>{adminProducts=data.sort((a,b)=>(a.featuredRank??999)-(b.featuredRank??999)||String(a.name).localeCompare(String(b.name),'ko'));renderProducts();renderDashboard()});
 watch('orders',data=>{orders=data.sort((a,b)=>new Date(dateValue(b.createdAt))-new Date(dateValue(a.createdAt)));renderOrders();renderDashboard();renderCustomers();adminUI?.renderSummaries()});
 watch('qna',data=>{qna=data.sort((a,b)=>new Date(dateValue(b.createdAt))-new Date(dateValue(a.createdAt)));renderQnaTable();adminUI?.renderSupport()});
 watch('reviews',data=>{reviews=data.sort((a,b)=>new Date(dateValue(b.createdAt))-new Date(dateValue(a.createdAt)));renderReviews();adminUI?.renderSummaries()});
 watch('notices',data=>{notices=data.sort((a,b)=>Number(b.pinned)-Number(a.pinned)||new Date(dateValue(b.createdAt))-new Date(dateValue(a.createdAt)));renderNotices()});
 watch('users',data=>{customers=data;renderCustomers()});
 subscriptions.push(onSnapshot(doc(db,'storefront','popup'),snap=>{popup=snap.exists()?{id:snap.id,...snap.data()}:null;loadPopupForm()}));
}

function mainItem(order){return order.items?.[0]||{name:'상품 정보 없음',image:'assets/moodnote-mark-v2.svg',quantity:1,option:'기본 옵션'}}
function orderProductHTML(order){const item=mainItem(order),extra=Math.max(0,(order.items?.length||1)-1);return `<div class="order-product"><img src="${esc(item.image)}" alt=""/><div><span>${esc(item.name)}${extra?` 외 ${extra}건`:''}</span><small>${esc(item.option||'기본 옵션')} · ${item.quantity||1}개</small></div></div>`}
function statusBadge(status){return `<span class="status-badge ${statusClass[status]||''}">${esc(status)}</span>`}
function renderSalesChart(values=[0,0,0,0,0,0,0]){const max=Math.max(1,...values);$('#sales-chart').innerHTML=values.map((value,index)=>`<div class="chart-day"><i style="--h:${Math.max(4,value/max*100)}%"></i><span>${index===0?'7일 전':index===6?'오늘':''}</span></div>`).join('')}
function renderDashboard(){adminUI?.renderDashboard()}
function renderOrders(){adminUI?.renderOrders()}
function renderStockAlerts(){const low=adminProducts.filter(product=>Number(product.stock)<=8).slice(0,4);$('#stock-alerts').innerHTML=low.map(product=>`<div class="stock-item"><img src="${esc(product.image)}" alt=""/><div><strong>${esc(product.name)}</strong><span>${esc(categoryNames[product.category]||product.category)} · 안전재고 10개</span></div><b>${Number(product.stock)}개</b></div>`).join('')||'<p class="empty-cell">재고 부족 상품이 없습니다.</p>'}
function renderProducts(){if(!$('#product-table'))return;const query=$('#product-search').value.trim().toLowerCase(),items=adminProducts.filter(product=>(productFilter==='all'||productFilter==='low'&&Number(product.stock)<=8||productFilter==='active'&&product.saleStatus==='판매 중')&&(!query||product.name.toLowerCase().includes(query)||product.maker.toLowerCase().includes(query)));$('#total-products').textContent=adminProducts.length;$('#active-products').textContent=adminProducts.filter(product=>product.saleStatus==='판매 중').length;$('#low-products').textContent=adminProducts.filter(product=>Number(product.stock)<=8).length;$('#product-result-count').textContent=`총 ${items.length}개 상품`;$('#product-table').innerHTML=items.map(product=>`<tr><td><input type="checkbox" aria-label="${esc(product.name)} 선택"/></td><td><div class="product-cell"><img src="${esc(product.image)}" alt=""/><div><strong>${esc(product.name)}</strong><small>${esc(product.maker)} · ${esc(categoryNames[product.category]||product.category)}</small></div></div></td><td><strong>${won(product.price)}</strong></td><td><span class="stock-number ${Number(product.stock)<=8?'low':''}">${Number(product.stock)}개</span></td><td><span class="status-badge ${product.saleStatus==='판매 중'?'active':''}">${esc(product.saleStatus)}</span></td><td>${displayDate(product.updatedAt)}</td><td><button class="row-action" data-edit-product="${esc(product.id)}">수정</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-cell">등록된 상품이 없습니다.</td></tr>';renderStockAlerts()}
function openProductEditor(id){const product=adminProducts.find(item=>item.id===id);if(!product)return;const form=$('#product-edit-form');form.dataset.productId=id;for(const key of ['name','maker','category','price','stock','saleStatus','badge','summary','detail'])if(form.elements[key])form.elements[key].value=product[key]??(key==='summary'?product.description:'')??'';form.elements.searchVisible.checked=product.searchVisible!==false;form.elements.featured.checked=Boolean(product.featured);form.elements.reviewEnabled.checked=product.reviewEnabled!==false;form.elements.qnaEnabled.checked=product.qnaEnabled!==false;$('#edit-product-image').src=product.image;$('#product-preview-link').href=`index.html#product/${encodeURIComponent(id)}`;adminUI.fillProduct(product);showView('product-edit')}
async function saveProductEditor(form){await adminUI.saveProduct(form,false)}
function parseSpec(text){return Object.fromEntries(String(text||'').split('\n').map(line=>line.split(':')).filter(parts=>parts.length>1).map(([key,...value])=>[key.trim(),value.join(':').trim()]).filter(([key,value])=>key&&value))}
async function createProduct(form){await adminUI.saveProduct(form,true)}

function renderQnaTable(){if(!$('#qna-table'))return;const query=$('#qna-search').value.trim().toLowerCase(),items=qna.filter(item=>item.productId!=='support').filter(item=>(qnaFilter==='all'||qnaFilter==='waiting'&&item.status==='waiting'||qnaFilter==='done'&&item.status==='done'||qnaFilter==='secret'&&item.secret)&&(!query||String(item.title).toLowerCase().includes(query)||String(item.content).toLowerCase().includes(query)||String(item.product).toLowerCase().includes(query)));$('#qna-result-count').textContent=`총 ${items.length}건의 문의`;$('#qna-waiting-count').textContent=qna.filter(item=>item.productId!=='support'&&item.status==='waiting').length;$('#qna-table').innerHTML=items.map(item=>`<tr><td>${item.status==='done'?'<span class="status-badge done">답변 완료</span>':'<span class="status-badge ready">답변 대기</span>'}</td><td><div class="qna-title"><strong>${esc(item.title)}${item.secret?'<span class="secret-mark">비밀글</span>':''}</strong><small>${esc(item.content)}</small></div></td><td>${esc(item.product)}</td><td>${esc(item.customer)}</td><td>${displayDate(item.createdAt,true)}</td><td><button class="care-button ${item.status==='done'?'subtle':''}" data-qna-reply="${item.id}">${item.status==='done'?'답변 수정':'답변하기'}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty-cell">등록된 문의가 없습니다.</td></tr>'}
function renderReviews(){if(!$('#review-table'))return;const query=$('#review-search').value.trim().toLowerCase(),items=reviews.filter(item=>(reviewFilter==='all'||reviewFilter==='unanswered'&&!item.reply||reviewFilter==='photo'&&item.photo||reviewFilter==='hidden'&&item.hidden)&&(!query||String(item.text).toLowerCase().includes(query)||String(item.product).toLowerCase().includes(query)));$('#review-result-count').textContent=`총 ${items.length}개의 리뷰`;$('#unanswered-review-count').textContent=reviews.filter(item=>!item.reply).length;$('#hidden-review-count').textContent=reviews.filter(item=>item.hidden).length;$('#review-table').innerHTML=items.map(item=>`<tr><td><span class="stars">${'★'.repeat(item.rating)}${'☆'.repeat(5-item.rating)}</span></td><td><div class="review-content"><strong>${esc(item.text)}${item.photo?'<span class="photo-badge">사진</span>':''}</strong><span>${item.reply?'판매자 답글 등록됨':'판매자 답글 대기'}</span>${item.photo&&item.image?`<img class="review-photo" src="${esc(item.image)}" alt="리뷰 사진"/>`:''}</div></td><td>${esc(item.product)}</td><td>${esc(item.customer)}</td><td>${displayDate(item.createdAt)}</td><td><button class="visibility-button ${item.hidden?'hidden':''}" data-review-visibility="${item.id}">${item.hidden?'숨김':'공개'}</button></td><td><button class="care-button ${item.reply?'subtle':''}" data-review-reply="${item.id}">${item.reply?'답글 수정':'답글 작성'}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-cell">등록된 리뷰가 없습니다.</td></tr>'}
function openReplyDialog(mode,id){dialogMode=mode;dialogTarget=id;const item=(mode==='qna'?qna:reviews).find(row=>row.id===id);if(!item)return;$('#dialog-eyebrow').textContent=mode==='qna'?'PRODUCT Q&A':'REVIEW REPLY';$('#dialog-title').textContent=mode==='qna'?'상품 문의 답변':'리뷰 판매자 답글';$('#dialog-context').innerHTML=mode==='qna'?`<strong>${esc(item.title)}</strong><p>${esc(item.content)}</p><small>${esc(item.product)} · ${esc(item.customer)}</small>`:`<strong>${'★'.repeat(item.rating)} ${esc(item.text)}</strong><p>${esc(item.product)} · ${esc(item.customer)}</p>`;$('#dialog-reply').value=item.answer||item.reply||'';$('#admin-dialog').showModal();$('#dialog-reply').focus()}
async function saveDialogReply(){const reply=$('#dialog-reply').value.trim();if(!reply){toast('답변 내용을 입력해주세요.');return false}if(dialogMode==='qna')await updateDoc(doc(db,'qna',dialogTarget),{answer:reply,status:'done',updatedAt:serverTimestamp()});else await updateDoc(doc(db,'reviews',dialogTarget),{reply,updatedAt:serverTimestamp()});toast('답변을 저장했습니다.');return true}
async function toggleReviewVisibility(id){const item=reviews.find(row=>row.id===id);await updateDoc(doc(db,'reviews',id),{hidden:!item.hidden,updatedAt:serverTimestamp()});toast(item.hidden?'리뷰를 공개했습니다.':'리뷰를 숨겼습니다.')}

function renderNotices(){if(!$('#notice-table'))return;const query=$('#notice-search').value.trim().toLowerCase(),items=notices.filter(item=>(noticeFilter==='all'||noticeFilter==='published'&&item.published||noticeFilter==='draft'&&!item.published||noticeFilter==='pinned'&&item.pinned)&&(!query||item.title.toLowerCase().includes(query)));$('#notice-total').textContent=notices.length;$('#notice-published').textContent=notices.filter(item=>item.published).length;$('#notice-pinned').textContent=notices.filter(item=>item.pinned).length;$('#notice-draft').textContent=notices.filter(item=>!item.published).length;$('#notice-result-count').textContent=`총 ${items.length}개의 공지`;$('#notice-table').innerHTML=items.map(item=>`<tr><td>${item.published?'<span class="status-badge active">공개</span>':'<span class="status-badge">임시저장</span>'}</td><td><div class="notice-title"><strong>${item.pinned?'<span class="notice-pin">[고정]</span> ':''}${esc(item.title)}</strong><small>${esc(item.content.slice(0,65))}${item.content.length>65?'…':''}</small></div></td><td><span class="notice-type">${esc(item.type)}</span></td><td>${displayDate(item.createdAt)}</td><td>${Number(item.views||0).toLocaleString()}</td><td><button class="row-action" data-edit-notice="${item.id}">수정</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty-cell">등록된 공지가 없습니다.</td></tr>'}
function openNoticeEditor(id){const form=$('#notice-form'),item=id?notices.find(row=>row.id===id):null;form.hidden=false;form.closest('.notice-layout').classList.add('editing');form.dataset.noticeId=item?.id||'';form.elements.type.value=item?.type||'안내';form.elements.title.value=item?.title||'';form.elements.content.value=item?.content||'';form.elements.pinned.checked=Boolean(item?.pinned);form.elements.published.checked=item?Boolean(item.published):true;$('#notice-editor-title').textContent=item?'공지 수정':'새 공지 작성';form.elements.title.focus()}
function closeNoticeEditor(){const form=$('#notice-form');form.hidden=true;form.closest('.notice-layout').classList.remove('editing');form.reset()}
async function submitNotice(form,forceDraft=false){const id=form.dataset.noticeId||`N${Date.now()}`,existing=notices.find(item=>item.id===id),entry={id,type:form.elements.type.value,title:form.elements.title.value.trim(),content:form.elements.content.value.trim(),views:Number(existing?.views||0),pinned:form.elements.pinned.checked,published:forceDraft?false:form.elements.published.checked,createdAt:existing?.createdAt||serverTimestamp(),updatedAt:serverTimestamp()};if(!entry.title||!entry.content){toast('공지 제목과 내용을 입력해주세요.');return}await setDoc(doc(db,'notices',id),entry);closeNoticeEditor();toast(forceDraft?'공지를 임시저장했습니다.':'공지를 저장했습니다.')}
function syncPopupPreview(){const form=$('#popup-form'),theme=form.elements.theme.value;$('#popup-preview').className=`preview-popup ${theme}`;$('#preview-popup-title').textContent=form.elements.title.value||'팝업 제목';$('#preview-popup-message').textContent=form.elements.message.value||'팝업 안내 문구';$('#preview-popup-button').textContent=form.elements.buttonLabel.value||'자세히 보기';$('#popup-current-status').textContent=form.elements.enabled.checked?'노출 중':'노출 안 함';$('#popup-current-period').textContent=`${(form.elements.startDate.value||'-').replaceAll('-','.')} – ${(form.elements.endDate.value||'-').replaceAll('-','.')}`}
function loadPopupForm(){const form=$('#popup-form');if(popup)for(const key of ['adminName','title','message','buttonLabel','buttonLink','startDate','endDate','theme','position'])if(popup[key]!==undefined)form.elements[key].value=popup[key];form.elements.enabled.checked=Boolean(popup?.enabled);syncPopupPreview()}
async function savePopup(form){const settings={};for(const key of ['adminName','title','message','buttonLabel','buttonLink','startDate','endDate','theme','position'])settings[key]=form.elements[key].value.trim();settings.enabled=form.elements.enabled.checked;settings.updatedAt=serverTimestamp();await setDoc(doc(db,'storefront','popup'),settings);toast(settings.enabled?'팝업을 저장하고 노출을 시작했습니다.':'팝업을 저장했습니다.')}
function renderCustomers(){if(!$('#customer-table'))return;$('#customer-table').innerHTML=customers.map(user=>{const userOrders=orders.filter(order=>order.userId===user.uid&&['결제 완료','배송 준비','배송 중','배송 완료'].includes(order.status)),spent=userOrders.filter(order=>['결제 완료','배송 준비','배송 중','배송 완료'].includes(order.status)).reduce((sum,order)=>sum+Number(order.total||0),0);return `<tr><td><div class="customer-name"><span>${esc((user.displayName||'M').slice(0,1))}</span><div><strong>${esc(user.displayName||'회원')}</strong><small>${esc(user.email)}</small></div></div></td><td><span class="grade">${spent>=100000?'VIP':userOrders.length?'FAMILY':'NEW'}</span></td><td>${userOrders.length}건</td><td><strong>${won(spent)}</strong></td><td>${displayDate(userOrders[0]?.approvedAt||userOrders[0]?.createdAt)}</td><td>${user.news?'동의':'미동의'}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty-cell">가입한 고객이 없습니다.</td></tr>'}
function showView(name,updateHash=true){const next=$(`.admin-view[data-view="${name}"]`);if(!next)return;$$('.admin-view').forEach(view=>view.classList.toggle('active',view===next));$$('[data-admin-view]').forEach(button=>button.classList.toggle('active',button.dataset.adminView===name));if(updateHash)history.replaceState(null,'','#'+name);document.title=`${next.querySelector('h1')?.textContent||'무드노트'} | 무드노트 판매자센터`;window.scrollTo({top:0,behavior:'instant'});closeMobileMenu()}
function closeMobileMenu(){$('#admin-sidebar').classList.remove('open');$('#admin-overlay').hidden=true}

function exportOrders(){const cols=['주문번호','주문일시','상품·옵션·수량','주문자','연락처','수령인','우편번호','주소','배송메모','결제금액','상태','택배사','송장'];const lines=orders.map(o=>[o.id,dateValue(o.createdAt),(o.items||[]).map(i=>i.name+' / '+i.option+' / '+i.quantity).join('; '),o.customer,o.phone,o.address?.recipient,o.address?.zip,[o.address?.address,o.address?.address2].filter(Boolean).join(' '),o.address?.memo,o.total,o.status,o.carrier,o.trackingNumber]);const csv='\ufeff'+[cols,...lines].map(row=>row.map(value=>{let v=String(value??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'}).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='moodnote-orders.csv';link.click();URL.revokeObjectURL(url)}

document.addEventListener('click',async event=>{const nav=event.target.closest('[data-admin-view]');if(nav){showView(nav.dataset.adminView);return}const go=event.target.closest('[data-go-view]');if(go){showView(go.dataset.goView);return}const orderTab=event.target.closest('[data-status]');if(orderTab){orderFilter=orderTab.dataset.status;$$('#order-tabs button').forEach(b=>b.classList.toggle('active',b===orderTab));renderOrders();return}const productTab=event.target.closest('[data-product-filter]');if(productTab){productFilter=productTab.dataset.productFilter;$$('#product-tabs button').forEach(b=>b.classList.toggle('active',b===productTab));renderProducts();return}const qnaTab=event.target.closest('[data-qna-filter]');if(qnaTab){qnaFilter=qnaTab.dataset.qnaFilter;renderQnaTable();return}const reviewTab=event.target.closest('[data-review-filter]');if(reviewTab){reviewFilter=reviewTab.dataset.reviewFilter;renderReviews();return}const noticeTab=event.target.closest('[data-notice-filter]');if(noticeTab){noticeFilter=noticeTab.dataset.noticeFilter;renderNotices();return}if(event.target.closest('#mobile-menu')){$('#admin-sidebar').classList.add('open');$('#admin-overlay').hidden=false;return}if(event.target.closest('#admin-overlay')){closeMobileMenu();return}if(event.target.closest('#export-orders')){exportOrders();return}if(event.target.closest('#add-product')){showView('product-create');return}if(event.target.closest('#new-notice')){openNoticeEditor();return}const editNotice=event.target.closest('[data-edit-notice]');if(editNotice){openNoticeEditor(editNotice.dataset.editNotice);return}if(event.target.closest('#close-notice-editor')){closeNoticeEditor();return}if(event.target.closest('#save-notice-draft')){await submitNotice($('#notice-form'),true);return}if(event.target.closest('#preview-popup')){syncPopupPreview();return}if(event.target.closest('#disable-popup')){const form=$('#popup-form');form.elements.enabled.checked=false;await savePopup(form);return}const editProduct=event.target.closest('[data-edit-product]');if(editProduct){openProductEditor(editProduct.dataset.editProduct);return}const qnaReply=event.target.closest('[data-qna-reply]');if(qnaReply){openReplyDialog('qna',qnaReply.dataset.qnaReply);return}const reviewReply=event.target.closest('[data-review-reply]');if(reviewReply){openReplyDialog('review',reviewReply.dataset.reviewReply);return}const visibility=event.target.closest('[data-review-visibility]');if(visibility){await toggleReviewVisibility(visibility.dataset.reviewVisibility);return}});
document.addEventListener('change',async event=>{if(event.target.closest('#popup-form'))syncPopupPreview()});
document.addEventListener('input',event=>{if(event.target.id==='order-search')renderOrders();if(event.target.id==='product-search')renderProducts();if(event.target.id==='qna-search')renderQnaTable();if(event.target.id==='review-search')renderReviews();if(event.target.id==='notice-search')renderNotices();if(event.target.closest('#popup-form'))syncPopupPreview()});
document.addEventListener('submit',async event=>{if(event.target.id==='product-edit-form'){event.preventDefault();await adminUI.run(()=>saveProductEditor(event.target),event.submitter)}if(event.target.id==='product-create-form'){event.preventDefault();await adminUI.run(()=>createProduct(event.target),event.submitter)}if(event.target.id==='notice-form'){event.preventDefault();await submitNotice(event.target)}if(event.target.id==='popup-form'){event.preventDefault();await savePopup(event.target)}});
$('#dialog-save').addEventListener('click',async event=>{event.preventDefault();if(await saveDialogReply())$('#admin-dialog').close()});
$('#global-search').addEventListener('submit',event=>{event.preventDefault();const query=event.target.elements[0].value.trim();if(!query)return;const isOrder=query.toUpperCase().startsWith('MN')||orders.some(o=>[o.id,o.customer,o.phone].some(v=>String(v||'').toLowerCase().includes(query.toLowerCase())));showView(isOrder?'orders':'products');const target=isOrder?$('#order-search'):$('#product-search');target.value=query;target.dispatchEvent(new Event('input',{bubbles:true}))});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#global-search input').focus()}if(event.key==='Escape')closeMobileMenu()});

adminUI=initAdminOperations({app,auth,db,data:()=>({adminProducts,orders,qna,reviews,customers}),esc,toast,showView});
$('#today-label').textContent=new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date());showView((location.hash||'#dashboard').slice(1),false);renderProducts();renderOrders();renderQnaTable();renderReviews();renderNotices();renderCustomers();renderDashboard();
onAuthStateChanged(auth,user=>{subscriptions.forEach(stop=>stop());subscriptions=[];adminUI.stop();adminProducts=[];orders=[];qna=[];reviews=[];notices=[];customers=[];renderProducts();renderOrders();renderQnaTable();renderReviews();renderNotices();renderCustomers();renderDashboard();adminUI.renderSupport();if(!user){showGate();return}if(user.email!==ADMIN_EMAIL||!user.emailVerified){showGate('denied');return}unlock();$('.operator strong').textContent=user.displayName||'무드노트 운영자';$('.operator small').textContent=user.email;listen()});
